def validate_number(phone_number: str) -> str:
    cleaned = phone_number.replace('-', '')

    if cleaned.startswith('07'):
        if len(cleaned) == 11 and cleaned[2:].isdigit():
            return 'In with a chance'
    elif cleaned.startswith('+44'):
        if len(cleaned) == 13 and cleaned[3:].isdigit():
            return 'In with a chance'

    return 'Plenty more fish in the sea'
